let S, token, page='overview', cart=[], purchaseCart=[], category='All', query='', stockFilter='All', peopleFilter='customer';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupee=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((n||0)/100);
const qty=n=>Number(Number(n||0).toFixed(3)).toLocaleString('en-IN');
const today=()=>new Date().toLocaleDateString('en-CA'), date=s=>new Date(s).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
const sum=(a,key)=>a.reduce((n,r)=>n+(typeof key==='function'?key(r):Number(r[key]||0)),0);
const product=id=>S.products.find(p=>p.id==id), party=id=>S.parties.find(p=>p.id==id), stock=(id,loc)=>S.stocks.find(s=>s.product_id==id&&s.location===loc)?.quantity||0;
const liveDocs=()=>S.documents.filter(d=>!d.reversed), localLocation=()=>S.settings.device_location||'Outlet';
const iconPaths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',billing:'M4 3h16v18l-4-2-4 2-4-2-4 2z M8 7h8 M8 11h8 M8 15h4',inventory:'M3 6l9-4 9 4-9 5z M3 6v12l9 4 9-4V6 M12 11v11',purchases:'M3 5h2l3 12h10l3-9H6 M9 21h.01 M18 21h.01',cafe:'M4 4h13v8a6.5 6.5 0 0 1-13 0z M17 5h2a3 3 0 0 1 0 6h-2 M2 21h19',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 3a4 4 0 1 1 0 8 M20 21v-2a4 4 0 0 0-3-3 M9 3a4 4 0 1 0 0 8a4 4 0 0 0 0-8',reports:'M4 21h17 M7 17V9 M12 17V3 M17 17v-5',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
iconPaths.notifications=iconPaths.people;
const pages={notifications:'WhatsApp updates',overview:'Overview',billing:'Billing & invoices',inventory:'Inventory & transfers',purchases:'Purchases',cafe:'Café & recipes',people:'Customers & suppliers',reports:'Reports & expenses',settings:'Settings & sync'};
const icon=k=>`<svg viewBox="0 0 24 24"><path d="${iconPaths[k]}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className=error?'error-toast':'';$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6500)}
async function api(action,data={}){const r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Shop-Token':token},body:JSON.stringify(data)});const body=await r.json();if(!r.ok)throw Error(body.error);return body}
async function load(){const r=await fetch('/api/state');if(!r.ok)throw Error('Local app is unavailable. Keep its launcher window open.');S=await r.json();$('#device-badge').textContent=S.settings.device_location||'Warehouse + Outlet';$('#sync-status').textContent=S.settings.last_sync?'Last exchange: '+new Date(S.settings.last_sync).toLocaleTimeString(): 'Sync folder not connected';render()}
async function mutate(action,data,message){const r=await api(action,data);await load();if(message)toast(message);return r}
function navTo(name){page=name;query='';category='All';render();window.scrollTo(0,0)}
function render(){if(!S)return;$('#nav').innerHTML=Object.entries(pages).map(([k,v])=>`<button class="${page===k?'active':''}" onclick="navTo('${k}')">${icon(k)}<span>${v}</span></button>`).join('');$('#page-label').textContent=pages[page];$('#main').innerHTML=({notifications:notificationsPage,overview:overview,billing:billing,inventory:inventory,purchases:purchases,cafe:cafe,people:people,reports:reports,settings:settings})[page]();bindPage()}
const heading=(tag,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const empty=text=>`<div class="empty">${text}</div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${!rows.length?empty('No records yet. Add your first entry to get started.'):''}</div>`;
const selectOptions=(rows,selected)=>rows.map(r=>`<option value="${esc(r.id)}" ${String(r.id)===String(selected)?'selected':''}>${esc(r.name)}</option>`).join('');
const symbol=c=>({'Cold drinks':'🥤','Water':'◈','Packaged water':'◈','Juices':'🍊','Energy drinks':'ϟ','Ice cream':'🍦','Snacks':'▧','Coffee':'☕','Tea & coffee':'☕','Mojitos':'🍃','Ingredients':'◌','Dairy & milk':'🥛'}[c]||'▣');
function overview(){const sales=liveDocs().filter(d=>d.kind==='sale'&&d.date.slice(0,10)===today()), docs=liveDocs().filter(d=>d.kind==='sale');const low=S.products.filter(p=>p.kind!=='recipe'&&(p.price>0||p.cost>0||p.stock>0)&&p.stock<=p.minimum),totalSales=sum(sales,'total');return heading('BUSINESS AT A GLANCE','A good day starts here.','Everything happening at your trading warehouse and café outlet.',`<button class="btn secondary" onclick="runBackup()">↓ Back up data</button><button class="btn" onclick="navTo('billing')">＋ New bill <small>F2</small></button>`)+
`${S.settings.demo?'<div class="notice">Sample shop data is loaded. These are illustrative products, prices and recipes. Use a separate clean database for live trading.</div>':''}${S.sync_errors.length?'<div class="help">Sync needs attention: '+S.sync_errors.length+' transaction(s) are waiting. Open Settings to review them.</div>':''}
<div class="welcome-banner"><div><strong>Chill. Refresh. Enjoy. Always.</strong><p>Cold drinks, everyday essentials & a little café happiness.</p></div><div class="banner-decoration">✦ AH</div></div>
<div class="stats">${stat('Today’s sales',rupee(totalSales),'₹',sales.length+' bills recorded today')}${stat('Inventory value',rupee(sum(S.products,p=>p.stock*p.cost)),'▣','Across warehouse & outlet')}${stat('Customer dues',rupee(sum(S.parties.filter(p=>p.kind==='customer'),'balance')),'↗','Outstanding customer credit')}${stat('Low-stock products',low.length,'◷',low.length?'Review your reorder list':'Your shelves are in good shape')}</div>
<div class="dashboard-grid"><div class="card"><div class="card-head"><div><h2>Sales this week</h2><p>Your last 7 days, across both locations</p></div><span class="pill">${docs.length} total bills</span></div>${chart(docs)}</div><div class="card"><div class="card-head"><div><h2>Your business, together</h2><p>Two locations. One clear picture.</p></div></div><div class="mix-item"><div class="mix-icon">▣</div><div><strong>Trading warehouse</strong><small>${S.stocks.filter(s=>s.location==='Warehouse'&&s.quantity>0).length} stocked SKUs · direct customer billing</small></div><b>${rupee(sum(S.stocks.filter(s=>s.location==='Warehouse'),s=>s.quantity*(product(s.product_id)?.cost||0)))}</b></div><div class="mix-item"><div class="mix-icon">▤</div><div><strong>Café / shop outlet</strong><small>Takeaway café & packaged-goods billing</small></div><b>${rupee(sum(S.stocks.filter(s=>s.location==='Outlet'),s=>s.quantity*(product(s.product_id)?.cost||0)))}</b></div><div class="mix-item"><div class="mix-icon">☕</div><div><strong>Micro café</strong><small>${S.products.filter(p=>p.kind==='recipe').length} menu items · ingredient tracking</small></div><button class="text-btn" onclick="navTo('cafe')">View menu →</button></div><div style="padding:10px 23px 22px"><div class="help" style="margin:0">${S.settings.gst_enabled?'GST billing is enabled. Prices include applicable tax.':'GST is available. Add your registration details in Settings to enable tax invoices.'}</div></div></div></div>
<div class="dashboard-grid"><div class="card"><div class="card-head"><h2>Recent invoices</h2><button class="text-btn" onclick="invoiceList()">View all →</button></div>${documentTable(S.documents.filter(d=>d.kind==='sale').slice(0,5))}</div><div class="card"><div class="card-head"><h2>Stock to watch</h2><button class="text-btn" onclick="navTo('inventory')">View stock →</button></div>${low.length?low.slice(0,5).map(p=>`<div class="mix-item"><div class="mix-icon">${symbol(p.category)}</div><div><strong>${esc(p.name)}</strong><small>Reorder at ${qty(p.minimum)} ${esc(p.unit)}</small></div><span class="pill warn">${qty(p.stock)} left</span></div>`).join(''):empty('No low-stock alerts right now.')}</div></div>${!S.products.length?'<div class="notice">Start with Settings, add products and opening warehouse stock, then transfer stock to the outlet. You can also load sample data from Settings to explore.</div>':''}`}
function stat(label,value,ico,foot){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${ico}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function chart(docs){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA');return {label:d.toLocaleDateString('en-IN',{weekday:'short'}),value:sum(docs.filter(s=>s.date.slice(0,10)===key),'total')}});const max=Math.max(...days.map(d=>d.value),100);return `<div class="chart"><div class="chart-note">${rupee(sum(days,'value'))} <span style="color:#9da491">in the last 7 days</span></div><svg viewBox="0 0 600 180" preserveAspectRatio="none">${[20,65,110,155].map(y=>`<line x1="0" x2="600" y1="${y}" y2="${y}" stroke="#eef0e8" stroke-dasharray="4 5"/>`).join('')}${days.map((d,i)=>`<rect x="${30+i*81}" y="${155-d.value/max*130}" width="37" height="${Math.max(d.value/max*130,2)}" rx="4" fill="${i===6?'#bc984f':'#d7e3d3'}"><title>${d.label}: ${rupee(d.value)}</title></rect>`).join('')}</svg><div class="chart-labels">${days.map(d=>`<span>${d.label}</span>`).join('')}</div></div>`}
function documentTable(docs){return table(['Invoice','Customer / supplier','Amount','Status',''],docs.map(d=>`<tr><td><strong>${esc(d.id)}</strong><small>${date(d.date)} · ${esc(d.location)}</small></td><td>${esc(party(d.party_id)?.name||'Walk-in customer')}<small>${esc(d.payment)}</small></td><td>${rupee(d.total)}</td><td><span class="pill ${d.reversed?'red':d.paid<d.total?'warn':''}">${d.reversed?'Reversed':d.paid<d.total?'Part paid':'Paid'}</span></td><td><button class="text-btn" onclick="viewInvoice('${esc(d.id)}')">View →</button></td></tr>`))}
function billing(){const cats=['All',...new Set(S.products.filter(p=>p.kind!=='ingredient').map(p=>p.category))];return heading('POINT OF SALE','Let’s make a sale.','Quick billing for cold drinks, café favourites and everyday essentials.',`<button class="btn secondary" onclick="invoiceList()">▤ Invoice history</button>`)+`<div class="pos-layout"><div><div class="toolbar"><div class="search" style="width:100%"><input id="product-search" placeholder="Search product or scan barcode…  F3" value="${esc(query)}"></div></div><div class="tabs">${cats.map(c=>`<button class="${category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div id="product-results">${productCards()}</div><div class="help">F2: New bill · F3: Barcode search · F8: Checkout<br>Stock is deducted from ${esc(localLocation())}. ${S.settings.admin_device_id?isMainPC()?'This PC sells the unallocated balance.':'This till sells only its assigned stock allowance.':'Assign and pair this PC in Settings before live use.'} Cases convert to the pack quantity.</div></div><div class="card cart"><div class="cart-head"><h2>Current bill <span style="float:right;font-size:10px;color:#9a9f93">${esc(localLocation())}</span></h2><div style="display:flex;gap:6px;margin-bottom:8px"><input id="customer-mobile" type="tel" placeholder="Customer mobile (optional)"><button class="btn secondary small" onclick="findCustomerMobile()">Find</button></div><select id="sale-party" onchange="window.saleParty=this.value;window.priceTier=party(this.value)?.price_tier||'retail';render()"><option value="">Walk-in customer</option>${selectOptions(S.parties.filter(p=>p.kind==='customer'),window.saleParty)}</select><select style="margin-top:8px" onchange="window.priceTier=this.value;render()"><option value="retail" ${window.priceTier!=='wholesale'?'selected':''}>Retail price</option><option value="wholesale" ${window.priceTier==='wholesale'?'selected':''}>Wholesale price</option></select></div><div id="cart-items">${cartRows()}</div><div class="cart-totals"><div class="total-row"><span>Subtotal</span><span id="subtotal">${rupee(cartTotal())}</span></div><div class="total-row"><span>Discount ₹</span><input id="discount" type="number" min="0" step="0.01" value="${window.saleDiscount||0}" style="width:100px;padding:7px" oninput="window.saleDiscount=this.value;updateTotal()"></div><div class="total-row grand"><span>Total</span><span id="grand-total">${rupee(Math.max(0,cartTotal()-Math.round((window.saleDiscount||0)*100)))}</span></div><p style="font-size:10px">${S.settings.gst_enabled?'GST and applicable cess included':'GST not collected · registration not enabled'}</p></div><div class="cart-pay"><button class="btn gold" onclick="checkout()" ${!cart.length?'disabled':''}>Checkout & save bill <small>F8</small></button><button class="text-btn" style="width:100%;margin-top:13px" onclick="clearCart()">Clear bill</button></div></div></div>`}
function productCards(){const products=S.products.filter(p=>p.kind!=='ingredient'&&(category==='All'||p.category===category)&&(`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.size}`.toLowerCase().includes(query.toLowerCase())));return products.length?`<div class="product-grid">${products.map(p=>`<button class="product-card" onclick="addCart(${p.id})"><span class="product-symbol">${symbol(p.category)}</span><strong>${esc(p.name)}</strong><small>${p.kind==='recipe'?'Made fresh · recipe':qty(billStock(p.id))+' '+esc(p.unit)+' available'}</small><b>${rupee(p.price)}</b></button>`).join('')}</div>`:empty('No matching products. Add products in Inventory, or sync from the warehouse.')}
function salePrice(p){return window.priceTier==='wholesale'&&p.wholesale_price>0?p.wholesale_price:p.price}
function isMainPC(){return !S.settings.device_location||S.settings.device_id===S.settings.admin_device_id}
function billStock(id,loc=localLocation()){if(!S.settings.admin_device_id)return stock(id,loc);if(isMainPC())return Math.max(0,stock(id,loc)-sum(S.allocations.filter(a=>a.product_id==id&&a.location===loc),'quantity'));return S.allocations.find(a=>a.device_id===S.settings.device_id&&a.product_id==id&&a.location===loc)?.quantity||0}
function cartTotal(){return sum(cart,l=>Math.round(salePrice(product(l.id))*l.quantity))}
function cartRows(){return cart.length?`<div class="cart-items">${cart.map(l=>{const p=product(l.id);return `<div class="cart-line"><div class="cart-line-top"><strong>${esc(p.name)}</strong><span>${rupee(salePrice(p)*l.quantity)}</span></div><div class="cart-line-bottom"><div class="qty-control"><button onclick="changeQty(${l.id},${l.quantity-1})">−</button><input type="number" min="0.001" step="any" value="${l.quantity}" onchange="changeQty(${l.id},this.value)"><button onclick="changeQty(${l.id},${l.quantity+1})">＋</button></div><small>${esc(p.unit)} ${p.pack>1?`<button class="text-btn" onclick="changeQty(${l.id},${l.quantity+p.pack})">＋ case (${qty(p.pack)})</button>`:''}</small></div></div>`}).join('')}</div>`:empty('Your bill is empty.<br>Tap a product or scan a barcode.')}
function addCart(id){const p=product(id);if(p.kind!=='recipe'&&billStock(id)<=0)return toast('No stock at this location. Transfer stock from the warehouse first.',true);const l=cart.find(l=>l.id===id);if(l)l.quantity++;else cart.push({id,quantity:1});render()}
function changeQty(id,n){n=Number(n);if(!Number.isFinite(n))return;if(n<=0)cart=cart.filter(l=>l.id!==id);else cart.find(l=>l.id===id).quantity=n;render()}
function clearCart(){cart=[];window.saleDiscount=0;render()}
function updateTotal(){$('#grand-total').textContent=rupee(Math.max(0,cartTotal()-Math.round((window.saleDiscount||0)*100)))}
function openModal(title,body,footer=''){const d=$('#modal');$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-content"><div id="form-error" class="error" role="alert"></div>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal()}
function closeModal(){$('#modal').close()}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function dropdown(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const v=typeof o==='string'?o:o.value,n=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`}).join('')}</select></div>`}
function formModal(title,body,onSubmit,button='Save'){openModal(title,`<form id="edit-form">${body}<button type="submit" hidden></button></form>`,`<button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn gold" id="form-submit" onclick="document.getElementById('edit-form').requestSubmit()">${button}</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();$('#form-error').textContent='';$('#form-submit').disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await onSubmit(data);if($('#edit-form')===e.target)closeModal()}catch(err){$('#form-error').textContent=err.message}finally{if($('#form-submit'))$('#form-submit').disabled=false}}}
function checkout(){if(!cart.length)return;const total=cartTotal()-Math.round((window.saleDiscount||0)*100);if(total<0)return toast('Discount exceeds total.',true);formModal('Complete sale',`<div class="report-number">${rupee(total)}</div><p>${esc(party(window.saleParty)?.name||'Walk-in customer')} · ${esc(localLocation())}</p><div class="help">Save the bill before collecting or printing. UPI and card entries record payment; they do not charge the customer.</div><div class="form-grid">${dropdown('Payment method','payment',['Cash','UPI','Card','Bank'],'Cash')}${field('Amount received ₹','paid',total/100,'number','min="0" step="0.01" required')}${field('Place of supply (state code)','supply_state',party(window.saleParty)?.gstin?.slice(0,2)||S.settings.state,'text','pattern="[0-9]{2}" maxlength="2"')}${field('Reference / note','reference')}</div><small>For customer credit, select a customer and enter the amount received. Change is not counted as revenue.</small>`,async data=>{const r=await mutate('sale',{...data,price_tier:window.priceTier||'retail',party_id:window.saleParty||null,location:localLocation(),discount:window.saleDiscount||0,items:cart.map(l=>({product_id:l.id,quantity:l.quantity}))});cart=[];window.saleDiscount=0;render();closeModal();viewInvoice(r.id);toast('Sale saved. Stock and customer ledger updated.')},'Save invoice')}
function invoiceList(){openModal('Invoice history',`<div class="search" style="margin-bottom:20px"><input id="invoice-search" placeholder="Find invoice or customer"></div><div id="invoice-results">${documentTable(S.documents.filter(d=>d.kind==='sale'))}</div>`);$('#invoice-search').oninput=e=>{$('#invoice-results').innerHTML=documentTable(S.documents.filter(d=>d.kind==='sale'&&(`${d.id} ${party(d.party_id)?.name||''}`).toLowerCase().includes(e.target.value.toLowerCase())))};}
function receiptHTML(d){const snap=d.snapshot,shop=snap.shop,items=snap.items,gst=sum(items,'gst_amount'),cess=sum(items,'cess_amount');return `<div class="receipt-preview"><div class="receipt-shop"><h2>${esc(shop.name)}</h2><p>${esc(shop.address)}</p><small>${shop.phone?'Tel: '+esc(shop.phone)+'<br>':''}${shop.gst_enabled?'GSTIN: '+esc(shop.gstin):'GST not collected'}</small><h3 style="margin:17px 0 4px">${d.reversed?'REVERSED · ':''}${d.kind==='purchase'?'PURCHASE RECORD':shop.gst_enabled?'TAX INVOICE':'SALE RECEIPT'}</h3></div><p style="font-size:11px">No: <b>${esc(d.id)}</b><br>${date(d.date)} ${new Date(d.date).toLocaleTimeString('en-IN')} · ${esc(d.location)}<br>${d.kind==='purchase'?'Supplier':'Customer'}: ${esc(snap.party.name||'Walk-in customer')}${snap.party.gstin?'<br>GSTIN: '+esc(snap.party.gstin):''}${snap.party.address?'<br>'+esc(snap.party.address):''}<br>Place of supply: ${esc(snap.supply_state)} ${shop.gst_enabled?'· '+esc(snap.tax_type):''}</p>${table(['Item','Qty','Rate','Total'],items.map(i=>`<tr><td>${esc(i.name)}<small>${i.hsn?'HSN/SAC '+esc(i.hsn):''}${shop.gst_enabled?' · GST '+i.gst+'%'+(i.cess?' / Cess '+i.cess+'%':''):''}</small></td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${rupee(i.price)}</td><td>${rupee(i.total)}</td></tr>`))}<div class="total-row"><span>Discount included</span><span>${rupee(d.discount)}</span></div>${shop.gst_enabled?`<div class="total-row"><span>Taxable value</span><span>${rupee(d.total-d.tax)}</span></div>${snap.tax_type==='IGST'?`<div class="total-row"><span>IGST</span><span>${rupee(gst)}</span></div>`:`<div class="total-row"><span>CGST</span><span>${rupee(sum(items,'cgst_amount'))}</span></div><div class="total-row"><span>SGST</span><span>${rupee(sum(items,'sgst_amount'))}</span></div>`}${cess?`<div class="total-row"><span>Cess</span><span>${rupee(cess)}</span></div>`:''}`:''}<div class="total-row grand"><span>Total</span><span>${rupee(d.total)}</span></div><div class="total-row"><span>Paid · ${esc(d.payment)}</span><span>${rupee(d.paid)}</span></div><div class="total-row"><span>Credit at issue</span><span>${rupee(d.total-d.paid)}</span></div>${d.reference?`<p style="font-size:10px">Reference: ${esc(d.reference)}</p>`:''}<p style="text-align:center;font-size:11px;margin-top:24px">Thank you for shopping with us.<br>Chill · Refresh · Enjoy · Always</p><p style="text-align:center;font-size:9px;margin-top:7px">Authorised signatory: __________________</p></div>`}
function viewInvoice(id){const d=S.documents.find(d=>d.id===id);openModal(d.kind==='sale'?'Invoice details':'Purchase record',receiptHTML(d),`${!d.reversed?`<button class="btn danger small" onclick="reverseDocument('${esc(id)}')">Reverse full ${d.kind==='sale'?'bill':'purchase'}</button>`:''}<button class="btn secondary" onclick="closeModal()">Close</button><button class="btn gold" onclick="printInvoice('${esc(id)}')">Print / Save PDF</button>`)}
function printInvoice(id){$('#print-area').innerHTML=receiptHTML(S.documents.find(d=>d.id===id));let st=$('#print-format');if(!st){st=document.createElement('style');st.id='print-format';document.head.appendChild(st)}const width=S.settings.printer;st.textContent=width==='A4'?'@media print{#print-area{max-width:190mm;margin:auto}}':`@media print{#print-area{width:${width==='58'?'48':'70'}mm;margin:0}#print-area .receipt-preview td{font-size:9px}} @page{size:${width}mm auto;margin:4mm}`;window.print()}
function reverseDocument(id){const d=S.documents.find(d=>d.id===id);formModal('Reverse full document',`<div class="help">This restores the original stock movements and reverses outstanding credit. ${rupee(d.paid)} paid by ${esc(d.payment)} must be refunded or reconciled outside the app. This is a full internal reversal; a statutory GST credit note is not generated.</div>${field('Reason','reason','','text','required')}`,async data=>{const r=await mutate('reverse',{id,...data},'Document reversed. Refund to reconcile: '+rupee(d.paid));return r},'Reverse document')}
function inventory(){const locs=['All','Warehouse','Outlet'], filtered=S.products.filter(p=>(`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.size}`.toLowerCase().includes(query.toLowerCase())));return heading('STOCK CONTROL','Every bottle accounted for.','Track packaged products and café ingredients at both locations.',`<button class="btn secondary" onclick="allocationList()">▣ PC stock allowances</button><button class="btn secondary" onclick="transferForm()">⇄ Stock transfer</button><button class="btn" onclick="productForm()">＋ Add product</button>`)+`<div class="toolbar"><div class="search"><input id="inventory-search" placeholder="Search name or barcode…" value="${esc(query)}"></div><div class="actions"><button class="btn secondary small" onclick="adjustForm()">Adjust / wastage</button><button class="btn secondary small" onclick="movementList()">Movement history</button><button class="btn secondary small" onclick="importForm()">Import CSV</button><button class="btn secondary small" onclick="loadCatalogue()">Starter catalogue</button><button class="btn secondary small" onclick="exportStock()">Export CSV</button></div></div><div class="tabs">${locs.map(l=>`<button class="${stockFilter===l?'active':''}" onclick="stockFilter='${l}';render()">${l==='All'?'Both locations':l}</button>`).join('')}</div><div class="card" id="inventory-results">${inventoryTable(filtered)}</div><div class="help">One base unit per product: bottles, packs, ml or grams. Cases convert to the configured number of base units. Expiry is tracked per SKU in this version; separate batches need separate SKUs.</div>`}
function inventoryTable(products){return table(['Product','Category','Warehouse','Outlet','Selling price','GST / cess','Stock status',''],products.map(p=>{const count=stockFilter==='All'?p.stock:stock(p.id,stockFilter);return `<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)}${p.barcode?' · ▥ '+esc(p.barcode):''} · ${p.kind==='recipe'?'Recipe':esc(p.unit)}${p.expiry?' · Exp '+esc(p.expiry):''}</small></td><td>${esc(p.category)}</td><td>${p.kind==='recipe'?'—':qty(stock(p.id,'Warehouse'))}</td><td>${p.kind==='recipe'?'Made fresh':qty(stock(p.id,'Outlet'))}</td><td>${rupee(p.price)}</td><td>${p.gst}%${p.cess?' + '+p.cess+'%':''}</td><td><span class="pill ${p.kind!=='recipe'&&count<=p.minimum?'warn':''}">${p.kind==='recipe'?'Recipe':!p.price&&!p.cost&&!p.stock?'Needs setup':count<=p.minimum?'Low stock':'In stock'}</span></td><td><button class="text-btn" onclick="productForm(${p.id})">Edit</button></td></tr>`}))}
function productForm(id){const p=id?product(id):{category:'Cold drinks',unit:'bottle',kind:'stock',price:0,cost:0,gst:0,cess:0,minimum:12,pack:24};const categories=['Cold drinks','Packaged water','Juices','Energy drinks','Ice cream','Snacks','Tea & coffee','Dairy & milk','Mojitos','Coffee','Ingredients'];if(!categories.includes(p.category))categories.push(p.category);formModal(id?'Edit product':'Add product',`<div class="form-grid">${field('Product name','name',p.name,'text','required')}${field('Internal SKU','sku',p.sku,'text','required')}${field('Manufacturer barcode (scan pack)','barcode',p.barcode)}${field('Brand','brand',p.brand)}${field('Pack size','size',p.size,'text','list="size-presets"')}${field('Packaging','packaging',p.packaging,'text','list="pack-presets"')}${field('MRP ₹ (0 if not applicable)','mrp',(p.mrp||0)/100,'number','min="0" step="0.01"')}${field('Wholesale price ₹ per base unit','wholesale_price',(p.wholesale_price||0)/100,'number','min="0" step="0.01"')}${dropdown('Category','category',categories,p.category)}${dropdown('Product type','kind',[{value:'stock',label:'Packaged stock'},{value:'ingredient',label:'Café ingredient'},{value:'recipe',label:'Café recipe / menu item'}],p.kind)}${field('Base unit (bottle, ml, g, cup)','unit',p.unit,'text','required')}${field('Base units per case / pack','pack',p.pack,'number','min="1" step="any" required')}${field('Selling price ₹ (tax inclusive)','price',p.price/100,'number','min="0" step="0.01" required')}${field('Purchase cost ₹ per base unit','cost',p.cost/100,'number','min="0" step="0.01" required')}${field('GST rate %','gst',p.gst,'number','min="0" max="100" step="any"')}${field('Cess rate % (if applicable)','cess',p.cess,'number','min="0" max="100" step="any"')}${field('HSN / SAC','hsn',p.hsn)}${field('Low-stock threshold','minimum',p.minimum,'number','min="0" step="any"')}${field('Expiry date (optional)','expiry',p.expiry,'date')}${!id?field('Opening stock in base units','stock',0,'number','min="0" step="any"')+dropdown('Opening stock location','location',['Warehouse','Outlet'],'Warehouse'):''}</div><datalist id="size-presets">${['100 ml','150 ml','160 ml','180 ml','200 ml','250 ml','300 ml','330 ml','350 ml','400 ml','450 ml','473 ml','500 ml','600 ml','650 ml','750 ml','1 L','1.2 L','1.25 L','1.5 L','1.75 L','2 L','2.25 L','3 L','5 L','10 L','20 L','25 g','50 g','75 g','100 g','150 g','200 g','250 g','500 g','1 kg','2 kg','5 kg','Small pack','Regular pack'].map(v=>`<option value="${v}">`).join('')}</datalist><datalist id="pack-presets">${['PET bottle','Glass bottle','Can','Carton','Cup','Sachet','Pack','Tub','Jar','Case','Crate'].map(v=>`<option value="${v}">`).join('')}</datalist><label class="check"><input type="checkbox" name="tax_verified" ${p.tax_verified?'checked':''}> HSN/SAC and tax rate have been checked for this product</label><div class="help">Rates depend on classification and registration. Use current supplier invoices and your accountant’s advice. Café ingredients must use the same units as the recipe.</div>`,data=>mutate('product',{...data,id:id||null},id?'Product updated.':'Product added.'))}
function transferForm(){formModal('Transfer stock between locations',`${dropdown('Product','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name}))) }<div class="form-grid">${dropdown('Dispatch from','source',['Warehouse','Outlet'],S.settings.device_location||'Warehouse')}${dropdown('Send to','target',['Warehouse','Outlet'],S.settings.device_location==='Outlet'?'Warehouse':'Outlet')}${field('Quantity in base units','quantity','','number','min="0.001" step="any" required')}${field('Transfer note','note','Stock transfer')}</div><div class="help">Stock leaves the source and is allocated to the destination. The receiving PC sees it after sync. Only dispatch goods you have actually sent.</div>`,data=>mutate('transfer',data,'Transfer saved. Sync both PCs to exchange the stock movement.'))}
function adjustForm(){formModal('Stock adjustment / wastage',`${dropdown('Product','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name})))}${dropdown('Location','location',['Warehouse','Outlet'],localLocation())}${field('Quantity change (negative for wastage)','quantity','','number','step="any" required')}${field('Reason','note','','text','required')}<div class="help">Examples: −2 bottles damaged, +3 bottles found during stock count. The reason is kept in the movement history.</div>`,data=>mutate('adjust',data,'Stock adjustment recorded.'))}
function movementList(){openModal('Recent stock movements',table(['Date','Product','Location','Change','Reason'],S.movements.map(m=>`<tr><td>${date(m.date)}<small>${esc(m.reference)}</small></td><td>${esc(product(m.product_id)?.name)}</td><td>${esc(m.location)}</td><td style="color:${m.quantity<0?'#a06e57':'#527558'}">${m.quantity>0?'+':''}${qty(m.quantity)}</td><td>${esc(m.note)}</td></tr>`)))}
function allocationList(){const me=S.settings.device_id;openModal('PC stock allowances',`<div class="notice">${S.online||S.settings.cloud_url?'The online owner manages allowances.':'No server is needed for shared-folder sync.'} The main warehouse PC grants stock already present at the till’s location. Each till can bill against its own allowance while disconnected. The main PC sells the unallocated balance. Allocations do not move physical stock between locations.</div>${isMainPC()?'<button class="btn gold small" onclick="allocationForm()">＋ Allocate stock to a PC</button>':''}${table(['PC','Location','Product','Unused allowance',''],S.allocations.filter(a=>a.quantity>0&&(isMainPC()||a.device_id===me)).map(a=>`<tr><td>${esc(S.devices.find(d=>d.id===a.device_id)?.name||a.device_id)}</td><td>${esc(a.location)}</td><td>${esc(product(a.product_id)?.name)}</td><td>${qty(a.quantity)} ${esc(product(a.product_id)?.unit)}</td><td>${a.device_id===me?`<button class="text-btn" onclick="releaseAllowance(${a.product_id})">Release unused</button>`:'Release on that PC'}</td></tr>`))}<p style="font-size:11px;margin-top:16px">Registered PCs: ${S.devices.map(d=>esc(d.name)+' ('+esc(d.location)+')').join(', ')||'Pair a PC in Settings first.'}</p>`)}
function allocationForm(){const devices=S.devices.filter(d=>d.id!==S.settings.admin_device_id);if(!devices.length)return toast('Sync the joining PC’s registration first, then sync the main PC.',true);formModal('Allocate offline stock to a till',`${dropdown('Target PC','device_id',devices.map(d=>({value:d.id,label:d.name+' · '+d.location})))}${dropdown('Product / café ingredient','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name})))}${field('Quantity in base units','quantity','','number','min="0.001" step="any" required')}<div class="help">Allocate only stock at the target location. For café supplies: transfer Warehouse → Outlet first, then allocate those ingredients to the café PC. Sync the main PC and the till to deliver the allowance.</div>`,data=>mutate('allocate',data,'Allowance saved. Sync to deliver it to the till.'))}
function releaseAllowance(id){formModal('Release unused stock allowance',`${field('Unused quantity to release','quantity','','number','min="0.001" step="any" required')}<div class="help">This PC stops using the released quantity immediately. The main PC can use or reassign it after both PCs sync. A main PC cannot take an allowance back while the till may be selling offline.</div>`,data=>mutate('release_allocation',{...data,product_id:id},'Unused allowance released. Sync with the main PC.'))}
function purchases(){return heading('SUPPLIER PURCHASES','Stock coming in.','Receive bottles, cases and ingredients. Keep supplier dues in view.',`<button class="btn" onclick="purchaseForm()">＋ Receive purchase</button>`)+`<div class="stats">${stat('Purchases recorded',rupee(sum(liveDocs().filter(d=>d.kind==='purchase'),'total')),'↓','All recorded supplier purchases')}${stat('Supplier dues',rupee(sum(S.parties.filter(p=>p.kind==='supplier'),'balance')),'↗','Outstanding purchase credit')}${stat('Suppliers',S.parties.filter(p=>p.kind==='supplier').length,'♙','Your purchase partners')}${stat('Warehouse stock value',rupee(sum(S.stocks.filter(s=>s.location==='Warehouse'),s=>s.quantity*(product(s.product_id)?.cost||0))),'▣','At average acquisition cost')}</div><div class="card"><div class="card-head"><h2>Purchase history</h2><button class="text-btn" onclick="partyForm('supplier')">＋ Add supplier</button></div>${documentTable(S.documents.filter(d=>d.kind==='purchase'))}</div>`}
function purchaseForm(){if(!S.parties.some(p=>p.kind==='supplier'))return partyForm('supplier');purchaseCart=[];formModal('Receive supplier purchase',`${dropdown('Supplier','party_id',S.parties.filter(p=>p.kind==='supplier').map(p=>({value:p.id,label:p.name})))}<div class="form-grid">${dropdown('Receive at','location',['Warehouse','Outlet'],S.settings.device_location||'Warehouse')}${field('Supplier invoice reference','reference','','text','required')}</div><label>Purchase items (base units; tax-inclusive cost)</label><div id="purchase-lines"></div><button type="button" class="btn secondary small" onclick="addPurchaseLine()">＋ Add item</button><div class="form-grid" style="margin-top:20px">${dropdown('Payment method','payment',['Cash','UPI','Card','Bank'],'Cash')}${field('Amount paid ₹','paid',0,'number','min="0" step="0.01" required')}</div><div class="help" id="purchase-total">Add the products on the supplier’s invoice. Stock increases and the unpaid amount becomes a supplier due.</div>`,async data=>{const items=Array.from(document.querySelectorAll('.purchase-line')).map(el=>({product_id:el.querySelector('select').value,quantity:el.querySelector('[data-qty]').value,price:el.querySelector('[data-price]').value}));await mutate('purchase',{...data,items},'Purchase saved. Stock and supplier ledger updated.');});addPurchaseLine()}
function addPurchaseLine(){const el=document.createElement('div');el.className='purchase-line form-grid';el.style.cssText='padding:13px;background:#f7f8f4;border-radius:6px;margin:10px 0';el.innerHTML=`<div class="field span2"><select onchange="this.closest('.purchase-line').querySelector('[data-price]').value=product(this.value).cost/100;purchaseTotal()">${selectOptions(S.products.filter(p=>p.kind!=='recipe'))}</select></div><div><label>Base-unit quantity</label><input data-qty type="number" min="0.001" step="any" value="1" oninput="purchaseTotal()" required></div><div><label>Unit cost ₹ (incl. tax)</label><input data-price type="number" min="0" step="0.01" value="${(S.products.find(p=>p.kind!=='recipe')?.cost||0)/100}" oninput="purchaseTotal()" required></div><button type="button" class="text-btn" onclick="this.closest('.purchase-line').remove();purchaseTotal()">Remove</button>`;$('#purchase-lines').appendChild(el);purchaseTotal()}
function purchaseTotal(){const total=Array.from(document.querySelectorAll('.purchase-line')).reduce((n,el)=>n+Math.round(Number(el.querySelector('[data-qty]').value)*Number(el.querySelector('[data-price]').value)*100),0);$('#purchase-total').textContent='Purchase total: '+rupee(total)+' · Enter the amount paid; the remainder becomes supplier credit.'}
function cafe(){const menu=S.products.filter(p=>p.kind==='recipe');return heading('TAKE & GO CAFÉ','A little café happiness.','Manage fresh drinks and the ingredients behind every cup.',`<button class="btn secondary" onclick="navTo('billing')">Open billing</button><button class="btn" onclick="productForm()">＋ Add menu item</button>`)+`<div class="notice">A café sale deducts recipe ingredients from the outlet automatically. Receive ingredients at the warehouse, then transfer them to the outlet before serving.</div><div class="product-grid">${menu.map(p=>{const r=S.recipes.filter(r=>r.product_id===p.id);const cost=sum(r,r=>r.quantity*(product(r.ingredient_id)?.cost||0));const available=r.length?Math.min(...r.map(r=>Math.floor(stock(r.ingredient_id,'Outlet')/r.quantity))):0;return `<div class="card"><div class="card-content"><span style="font-size:33px">${symbol(p.category)}</span><h3 style="margin:16px 0 9px">${esc(p.name)}</h3><p>${rupee(p.price)} <span style="font-size:11px">per ${esc(p.unit)}</span></p><p style="font-size:11px;margin-top:8px">Recipe cost: ${rupee(cost)}<br>${available} servings available at outlet</p><div class="help">${r.length?r.map(r=>esc(product(r.ingredient_id)?.name)+' · '+qty(r.quantity)+' '+esc(product(r.ingredient_id)?.unit)).join('<br>'):'Recipe not configured. Add ingredients before billing.'}</div><button class="btn secondary small" onclick="recipeForm(${p.id})">Edit recipe</button></div></div>`}).join('')}</div>${!menu.length?empty('Add a product with type “Café recipe / menu item”, then set its recipe.'):''}<div class="card" style="margin-top:24px"><div class="card-head"><h2>Café ingredients</h2><button class="text-btn" onclick="navTo('inventory')">Manage stock →</button></div>${inventoryTable(S.products.filter(p=>p.kind==='ingredient'))}</div>`}
function recipeForm(id){if(!S.products.some(p=>p.kind==='ingredient'))return toast('Add café ingredients in Inventory first.',true);formModal('Recipe · '+esc(product(id).name),`<p style="font-size:12px;margin-bottom:18px">Quantities for one ${esc(product(id).unit)}. Include milk, syrup, coffee and packaging if you track it.</p><div id="recipe-lines"></div><button type="button" class="btn secondary small" onclick="addRecipeLine()">＋ Ingredient</button><div class="help">Recipe units must match the ingredient’s base unit. For example: 200 ml soda + 30 ml mint syrup for one mojito.</div>`,async()=>{const items=Array.from(document.querySelectorAll('.recipe-line')).map(el=>({ingredient_id:el.querySelector('select').value,quantity:el.querySelector('input').value}));await mutate('recipe',{product_id:id,items},'Recipe saved.')});const current=S.recipes.filter(r=>r.product_id===id);if(current.length)current.forEach(r=>addRecipeLine(r.ingredient_id,r.quantity));else addRecipeLine()}
function addRecipeLine(id,quantity=1){const el=document.createElement('div');el.className='recipe-line';el.innerHTML=`<select>${selectOptions(S.products.filter(p=>p.kind==='ingredient').map(p=>({...p,name:p.name+' ('+p.unit+')'})),id)}</select><input type="number" min="0.001" step="any" value="${quantity}" required><button type="button" onclick="this.parentElement.remove()">×</button>`;$('#recipe-lines').appendChild(el)}
function people(){return heading('PEOPLE & LEDGERS','Good relationships. Clear accounts.','Keep customer credit and supplier payments easy to follow.',`<button class="btn" onclick="partyForm('${peopleFilter}')">＋ Add ${peopleFilter}</button>`)+`<div class="tabs"><button class="${peopleFilter==='customer'?'active':''}" onclick="peopleFilter='customer';render()">Customers</button><button class="${peopleFilter==='supplier'?'active':''}" onclick="peopleFilter='supplier';render()">Suppliers</button></div><div class="card">${table(['Name','Contact','GSTIN','Outstanding',''],S.parties.filter(p=>p.kind===peopleFilter).map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></td><td>${esc(p.phone)||'—'}</td><td>${esc(p.gstin)||'—'}</td><td><span class="pill ${p.balance?'warn':''}">${rupee(p.balance)}</span></td><td><button class="text-btn" onclick="ledger(${p.id})">Profile & ledger</button><button class="text-btn" onclick="partyForm('${peopleFilter}',${p.id})">Edit profile</button>${p.balance?`<button class="btn secondary small" onclick="paymentForm(${p.id})">${p.kind==='customer'?'Collect':'Pay'}</button>`:''}</td></tr>`))}</div>`}
function partyForm(kind='customer',id){const p=id?party(id):{};formModal((id?'Edit ':'Add ')+kind,`<div class="form-grid">${field('Name / business name','name',p.name,'text','required')}${field('Phone','phone',p.phone,'tel')}${field('Email','email',p.email,'email')}${field('GSTIN (optional)','gstin',p.gstin,'text','maxlength="15"')}${field('Billing address','address',p.address)}${dropdown('Preferred price tier','price_tier',['retail','wholesale'],p.price_tier||'retail')}${field('Credit limit ₹ (0 = no preset limit)','credit_limit',(p.credit_limit||0)/100,'number','min="0" step="0.01"')}${field('Customer notes','notes',p.notes)}</div><label class="check"><input type="checkbox" name="whatsapp_opt_in" ${p.whatsapp_opt_in?'checked':''}> Customer agreed to WhatsApp receipts and payment notifications</label><div class="help">Editing a profile preserves its purchases, payments and outstanding balance. The main PC controls credit limits. Invoice details remain as issued.</div>`,data=>mutate('party',{...data,id:id||null,kind},id?'Profile updated.':kind+' added.'))}
function paymentForm(id){const p=party(id);formModal(p.kind==='customer'?'Record customer payment':'Record supplier payment',`<h3>${esc(p.name)}</h3><p style="margin-bottom:20px">Outstanding: ${rupee(p.balance)}</p>${field('Payment amount ₹','amount',p.balance/100,'number','min="0.01" step="0.01" required')}${dropdown('Payment method','method',['Cash','UPI','Card','Bank'],'Cash')}${field('Reference / note','note')}`,data=>mutate('payment',{...data,party_id:id},'Payment recorded. Ledger updated.'))}
function ledger(id){const p=party(id),docs=S.documents.filter(d=>d.party_id===id),pay=S.payments.filter(r=>r.party_id===id);openModal('Ledger · '+esc(p.name),`<div class="report-number">${rupee(p.balance)}</div><p style="margin-bottom:23px">${p.kind==='customer'?'Receivable from customer':'Payable to supplier'}</p><div class="notice">${esc(p.phone)||'No phone'} · ${esc(p.email)||'No email'}<br>${esc(p.address)}<br>${p.gstin?'GSTIN: '+esc(p.gstin)+'<br>':''}Preferred pricing: ${esc(p.price_tier||'retail')} · Credit limit: ${p.credit_limit?rupee(p.credit_limit):'Not preset'}<br>${esc(p.notes)}</div>${table(['Date','Entry','Credit / due','Paid / settled'],[...docs.map(d=>({date:d.date,entry:d.id+(d.reversed?' · REVERSED':''),due:d.reversed?0:d.total-d.paid,paid:d.reversed?0:d.paid})),...pay.map(r=>({date:r.date,entry:'Payment · '+r.method,due:-r.amount,paid:r.amount}))].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<tr><td>${date(r.date)}</td><td>${esc(r.entry)}</td><td>${rupee(r.due)}</td><td>${rupee(r.paid)}</td></tr>`))}`)}
let reportFrom='',reportTo='';
function reportDocuments(){return liveDocs().filter(d=>(!reportFrom||d.date.slice(0,10)>=reportFrom)&&(!reportTo||d.date.slice(0,10)<=reportTo))}
function reports(){const docs=reportDocuments(),sales=docs.filter(d=>d.kind==='sale'),purchases=docs.filter(d=>d.kind==='purchase'),ids=new Set(sales.map(d=>d.id)),cost=sum(S.lines.filter(l=>ids.has(l.document_id)),'cost'),expenses=S.expenses.filter(e=>(!reportFrom||e.date.slice(0,10)>=reportFrom)&&(!reportTo||e.date.slice(0,10)<=reportTo)),revenue=sum(sales,d=>d.total-d.tax),gstLines=sales.flatMap(d=>d.snapshot.items.map(i=>({...i,doc:d})));return heading('BUSINESS REPORTS','Know where you stand.','Sales, purchases, operating expenses and tax records in one place.',`<button class="btn secondary" onclick="exportSales()">↓ Sales CSV</button><button class="btn" onclick="expenseForm()">＋ Record expense</button>`)+`<div class="toolbar"><p style="font-size:12px">Reports include saved, unreversed transactions.</p><div class="range"><input id="report-from" type="date" value="${reportFrom}"><span>to</span><input id="report-to" type="date" value="${reportTo}"><button class="btn secondary small" onclick="reportFrom=$('#report-from').value;reportTo=$('#report-to').value;render()">Apply</button></div></div><div class="stats">${stat('Sales (including GST)',rupee(sum(sales,'total')),'₹',sales.length+' invoices in selected period')}${stat('Purchases',rupee(sum(purchases,'total')),'↓','Recorded purchase invoice value')}${stat('Operating expenses',rupee(sum(expenses,'amount')),'↗',expenses.length+' expense entries')}${stat('Estimated contribution',rupee(revenue-cost-sum(expenses,'amount')),'◴','Sales ex tax − recorded cost − expenses')}</div><div class="help">Contribution is a management estimate, not statutory profit. Recorded costs include purchase taxes; café ITC eligibility and formal accounting are not inferred. For GST filing, have your accountant review the exported sales records.</div><div class="dashboard-grid"><div class="card"><div class="card-head"><h2>GST sales summary</h2><button class="text-btn" onclick="exportGST()">Export details →</button></div>${table(['Tax category','Taxable value','GST','Cess'],[...new Set(gstLines.map(l=>l.gst+'|'+l.cess+'|'+l.doc.snapshot.tax_type))].map(k=>{const ls=gstLines.filter(l=>l.gst+'|'+l.cess+'|'+l.doc.snapshot.tax_type===k);return `<tr><td>${ls[0].gst}% · ${esc(ls[0].doc.snapshot.tax_type)}${ls[0].cess?' + '+ls[0].cess+'% cess':''}</td><td>${rupee(sum(ls,'taxable'))}</td><td>${rupee(sum(ls,'gst_amount'))}</td><td>${rupee(sum(ls,'cess_amount'))}</td></tr>`}))}</div><div class="card"><div class="card-head"><h2>Expenses</h2></div>${table(['Date','Expense','Amount'],expenses.map(e=>`<tr><td>${date(e.date)}</td><td>${esc(e.name)}<small>${esc(e.method)}</small></td><td>${rupee(e.amount)}</td></tr>`))}</div></div><div class="card"><div class="card-head"><h2>Payment methods at invoice issue</h2></div>${table(['Method','Sales received','Purchases paid'],['Cash','UPI','Card','Bank'].map(m=>`<tr><td>${m}</td><td>${rupee(sum(sales.filter(d=>d.payment===m),'paid'))}</td><td>${rupee(sum(purchases.filter(d=>d.payment===m),'paid'))}</td></tr>`))}</div>`}
function expenseForm(){formModal('Record shop expense',`${field('Expense description','name','','text','required')}<div class="form-grid">${field('Amount ₹','amount','','number','min="0.01" step="0.01" required')}${dropdown('Paid by','method',['Cash','UPI','Card','Bank'],'Cash')}</div>`,data=>mutate('expense',data,'Expense recorded.'))}
function settings(){const s=S.settings;return heading('YOUR SHOP, YOUR DATA','Set up Al Hidaya Traders.','Business details, printing, backups and offline transaction sync.')+`<form id="settings-form"><div class="settings-layout"><div class="card"><div class="card-head"><h2>Business & GST</h2></div><div class="card-content"><div class="form-grid">${field('Business name','name',s.name,'text','required')}${field('Phone','phone',s.phone,'tel')}${field('Business address','address',s.address)}${field('GSTIN','gstin',s.gstin,'text','maxlength="15"')}${field('State code (Karnataka = 29)','state',s.state,'text','pattern="[0-9]{2}" maxlength="2" required')}${field('Invoice prefix (1–2 characters)','invoice_prefix',s.invoice_prefix,'text','pattern="[A-Z0-9]{1,2}" maxlength="2" required')}</div><label class="check"><input type="checkbox" name="gst_enabled" ${s.gst_enabled?'checked':''}> Enable GST collection (regular GST registration)</label><div class="help">Includes HSN/SAC, CGST + SGST or IGST, and configurable percentage cess. Composition billing, statutory credit notes, e-invoice IRN, e-way bills and GST portal filing are not included yet.</div>${dropdown('Print layout','printer',[{value:'80',label:'80 mm thermal receipt'},{value:'58',label:'58 mm thermal receipt'},{value:'A4',label:'A4 invoice'}],s.printer)}<p style="font-size:11px">Use a Windows-installed printer and its print dialog. Barcode scanners must send the barcode as keyboard input followed by Enter. Direct cash-drawer and weighing-scale drivers are not included.</p></div></div><div class="card"><div class="card-head"><h2>Location, sync & backup</h2></div><div class="card-content">${s.cloud_url?`<div class="notice">Connected to ${esc(s.cloud_url)}. Bills save locally and exchange automatically when connected. This till uses reserved stock; purchases, catalogue and credit are managed online.</div>`:`<button type="button" class="btn gold" onclick="cloudPairForm()">Connect to online business</button><p class="help">Use a pairing code from the online owner account. Join only with an empty app or disposable sample data.</p>`}${dropdown('Setup type','setup_role',[{value:'owner',label:'First/main warehouse PC (one per business)'},{value:'join',label:'Join the existing business (additional PC)'}],s.setup_role)}${field('PC name','device_name',s.device_name,'text','placeholder="Warehouse Till 2 or Cafe Till 1"')}${dropdown('This PC’s location','device_location',[{value:'',label:'Unassigned (local exploration only)'},{value:'Warehouse',label:'Warehouse — trading & retail counter'},{value:'Outlet',label:'Outlet — café / shop'}],s.device_location)}${field('Shared sync folder on this PC','sync_folder',s.sync_folder,'text','placeholder="C:\\Users\\Owner\\OneDrive\\AlHidayaShared"')}${field('Additional backup folder (optional)','backup_folder',s.backup_folder,'text','placeholder="D:\\AlHidayaBackups"')}<div class="help">Each PC has its own SQLite database. No AWS server is required. Select the same shared cloud folder on your PCs and keep it available offline. Immutable transaction files are exchanged every 30 seconds; the cloud-folder app uploads them when online. Never put the live database in that folder.</div><p style="font-size:11px">Device ID: ${esc(s.device_id)}<br>Last exchange: ${s.last_sync?esc(new Date(s.last_sync).toLocaleString()):'Not configured'}<br>Last verified backup: ${s.last_backup?esc(new Date(s.last_backup).toLocaleString()):'No backup yet'}<br>Local backups run every 15 minutes while the app is open.</p><div class="actions" style="margin-top:20px"><button type="button" class="btn secondary small" onclick="runSync()">↻ Sync now</button><button type="button" class="btn secondary small" onclick="runBackup()">↓ Back up now</button><a class="btn secondary small" href="/api/backup-download" download="AlHidaya-backup.sqlite3">Download backup</a></div></div></div></div><div id="settings-error" class="error" style="margin-top:15px"></div><div class="actions" style="margin-top:20px"><button type="submit" class="btn gold">Save settings</button><button type="button" class="btn secondary" onclick="closeApp()">Close app safely</button>${!S.products.length?'<button type="button" class="btn secondary" onclick="loadDemo()">Explore sample shop</button>':''}</div></form>${S.sync_errors.length?`<div class="card" style="margin-top:22px"><div class="card-head"><h2>Sync needs attention</h2></div>${table(['Transaction','Issue'],S.sync_errors.map(e=>`<tr><td>${esc(e.id)}</td><td style="white-space:normal">${esc(e.message)}</td></tr>`))}</div>`:''}<div class="notice" style="margin-top:22px">For two PCs: assign Warehouse to the trading/retail counter and Outlet to the café/shop. Warehouse setup adds the starter catalogue automatically. Configure the shared folder and actual product details on the warehouse PC. Sync the warehouse, allow the folder to upload/download, then sync the outlet. Transfers and billing remain local when internet is unavailable. Additional PCs choose “Join the existing business”. Sync their registration to the main PC, allocate stock there, then sync the till before billing. Only the main PC can administer stock and issue customer credit.</div>`}
function bindPage(){if(page==='billing'){if($('#product-search')){$('#product-search').oninput=e=>{query=e.target.value;$('#product-results').innerHTML=productCards()};$('#product-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const p=S.products.find(p=>p.sku===e.target.value.trim()||p.barcode===e.target.value.trim());if(p&&p.kind!=='ingredient'){addCart(p.id);query='';$('#product-search').value='';$('#product-results').innerHTML=productCards();$('#product-search').focus()}else toast('Barcode not found. Add the manufacturer’s barcode as the SKU.',true)}}}document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()})}if(page==='inventory')$('#inventory-search').oninput=e=>{query=e.target.value;$('#inventory-results').innerHTML=inventoryTable(S.products.filter(p=>(p.name+' '+p.sku+' '+p.barcode).toLowerCase().includes(query.toLowerCase())))};if(page==='settings'&&S.settings.cloud_url){for(const name of ['name','phone','address','gstin','state','invoice_prefix','gst_enabled','setup_role','device_location','sync_folder']){const el=$('#settings-form [name='+name+']');if(el)el.disabled=true;}}if(page==='settings')$('#settings-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.gst_enabled=e.target.gst_enabled.checked;await mutate('settings',data,'Settings saved.')}catch(err){$('#settings-error').textContent=err.message}finally{button.disabled=false}}}
async function runSync(){try{const r=await mutate('sync');toast(r.message,r.pending>0)}catch(e){toast(e.message,true)}}
async function runBackup(){try{const r=await mutate('backup');toast(r.message)}catch(e){toast(e.message,true)}}
function loadDemo(){formModal('Explore sample data',`<div class="help">This adds sample stock, suppliers and café recipes. The database will be marked as a sample shop. For real trading, start with a separate empty data folder.</div>`,async()=>{await mutate('demo',{},'Sample shop loaded.');navTo('overview')},'Load sample shop')}
function loadCatalogue(){formModal('Add Indian starter catalogue',`<p>379 editable templates covering major beverage brands, common pack sizes, snacks, dairy, ice cream and café ingredients.</p><div class="help">These are product templates, not a current manufacturer catalogue. Availability and packaging vary by market. Existing SKUs stay as entered. New records start with zero stock and price, blank barcodes and unconfirmed tax rates. Scan real packs and enter your supplier’s details before trading.</div>`,async()=>{const r=await mutate('catalog');toast(r.count+' new product templates added.')},'Add catalogue')}
function parseCSV(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV has an unclosed quoted field.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);const headers=rows.shift()?.map(h=>h.trim().toLowerCase());if(!headers?.includes('name')||!headers?.includes('sku'))throw Error('CSV must contain name and sku columns. Download the template.');return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()]).filter(([h,v])=>v!=='')))}
function importForm(){formModal('Import products from CSV',`<p style="margin-bottom:18px">Import up to 1,000 rows at a time. Matching SKUs update product details; new SKUs create products. Existing stock is preserved.</p><button type="button" class="btn secondary small" onclick="downloadImportTemplate()">↓ Download CSV template</button><div class="field" style="margin-top:20px"><label for="import-file">Product CSV file</label><input id="import-file" type="file" accept=".csv,text/csv" required></div><div class="help">Required: name, sku, category and unit. Supported: barcode, brand, size, packaging, kind, price, cost, mrp, wholesale_price, gst, cess, hsn, tax_verified, pack, minimum, expiry, opening_stock and location. Price/cost values are rupees. Use tax_verified=true only after checking classification and rates. Opening stock is allowed only on new products.</div>`,async()=>{const file=$('#import-file').files[0];if(!file)throw Error('Choose a CSV file.');if(file.size>1000000)throw Error('CSV exceeds 1 MB.');const rows=parseCSV(await file.text());const r=await mutate('import_products',{rows});toast(r.count+' products imported.')},'Import products')}
function downloadImportTemplate(){csv('AlHidaya-product-import-template.csv',['name','sku','barcode','brand','size','packaging','category','unit','kind','price','cost','mrp','wholesale_price','gst','cess','hsn','tax_verified','pack','minimum','expiry','opening_stock','location'],[['Example beverage 250 ml','MY-SKU-001','','Example brand','250 ml','PET bottle','Cold drinks','bottle','stock',0,0,0,0,0,0,'','false',24,12,'',0,'Warehouse']])}
function closeApp(){formModal('Close Al Hidaya Traders',`<p>A verified local backup will be created before the app closes. You can then close the browser tab or run a newer Setup.exe to update.</p>`,async()=>{const r=await api('shutdown');closeModal();$('#main').innerHTML=heading('SESSION CLOSED','Shop data saved.',esc(r.message));toast(r.message)},'Back up & close')}
function csv(name,headers,rows){const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportStock(){csv('AlHidaya-stock.csv',['SKU','Product','Unit','Warehouse','Outlet','Total stock','Selling price','Recorded cost','GST %','Cess %','Expiry'],S.products.map(p=>[p.sku,p.name,p.unit,stock(p.id,'Warehouse'),stock(p.id,'Outlet'),p.stock,p.price/100,p.cost/100,p.gst,p.cess,p.expiry]))}
function exportSales(){csv('AlHidaya-sales.csv',['Invoice','Date','Location','Customer','Total','Tax','Paid at issue','Payment','Discount'],reportDocuments().filter(d=>d.kind==='sale').map(d=>[d.id,d.date,d.location,d.snapshot.party.name||'Walk-in',d.total/100,d.tax/100,d.paid/100,d.payment,d.discount/100]))}
function exportGST(){csv('AlHidaya-GST-sales.csv',['Invoice','Date','Customer GSTIN','Place of supply','HSN/SAC','Product','Quantity','GST rate','Cess rate','Taxable value','CGST','SGST','IGST','Cess','Total'],reportDocuments().filter(d=>d.kind==='sale').flatMap(d=>d.snapshot.items.map(i=>{const igst=d.snapshot.tax_type==='IGST';return [d.id,d.date,d.snapshot.party.gstin||'',d.snapshot.supply_state,i.hsn,i.name,i.quantity,i.gst,i.cess,i.taxable/100,(i.cgst_amount||0)/100,(i.sgst_amount||0)/100,igst?i.gst_amount/100:0,i.cess_amount/100,i.total/100]})))}
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key==='F2'){e.preventDefault();navTo('billing')}if(e.key==='F3'){e.preventDefault();navTo('billing');$('#product-search')?.focus()}if(e.key==='F8'&&page==='billing'){e.preventDefault();checkout()}});
function tick(){$('#clock').textContent=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})+' · '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,30000);
(async()=>{try{token=(await (await fetch('/api/session')).json()).token;await load()}catch(e){$('#main').innerHTML=heading('APP CONNECTION','Open the local app first.',esc(e.message))}})();
setInterval(async()=>{if(!S||$('#modal').open||cart.length||page==='settings'||page==='billing')return;try{await load()}catch{}},30000);

function findCustomerMobile(){const value=$('#customer-mobile').value.replace(/\D/g,'').slice(-10);if(value.length!==10)return toast('Enter a 10-digit mobile number.',true);const found=S.parties.filter(p=>p.kind==='customer'&&p.phone.replace(/\D/g,'').slice(-10)===value);if(found.length===1){window.saleParty=found[0].id;window.priceTier=found[0].price_tier;render();toast('Customer selected: '+found[0].name)}else if(found.length>1){toast('Multiple profiles use this mobile. Choose the correct customer from the list.',true)}else{partyForm('customer');$('#f-phone').value=value;toast('Create an optional customer profile. Walk-in billing remains available.')}}
function notificationsPage(){const s=S.settings;return heading('WHATSAPP UPDATES','Keep everyone informed.','Offline queue for customer notifications and internal business updates.',`<button class="btn secondary" onclick="whatsappSettings()">Configure WhatsApp</button><button class="btn" onclick="sendNotifications()">Process queue</button>`)+`<div class="notice">${s.whatsapp_enabled?'Automation enabled on the main PC.':'Automation is disabled until you configure your WhatsApp Business account.'} ${S.whatsapp_token_configured?'Sender credential saved on this PC.':'No sender credential on this PC.'}<br>API accepted means WhatsApp accepted the request. Delivery and read receipts need a public webhook, to be added with the server.</div><div class="card" style="margin-top:20px"><div class="card-head"><div><h2>Internal recipients</h2><p>Owner, warehouse and café staff · individual opted-in mobile numbers</p></div><button class="text-btn" onclick="internalContact()">＋ Add recipient</button></div>${table(['Name','Mobile','Notifications',''],S.internal_contacts.map(r=>`<tr><td>${esc(r.name)}</td><td>+${esc(r.phone)}</td><td>${r.opt_in?'Enabled':'Opted out'}</td><td><button class="text-btn" onclick="internalContact(${r.id})">Edit</button></td></tr>`))}</div><div class="card" style="margin-top:20px"><div class="card-head"><h2>Recent notification queue</h2><button class="text-btn" onclick="load()">Refresh</button></div>${table(['Created','Type / mobile','Status','Details'],S.notifications.map(n=>`<tr><td>${date(n.created)}</td><td>${esc(n.kind)}<small>+${esc(n.phone)}</small></td><td><span class="pill ${['failed','uncertain'].includes(n.status)?'warn':''}">${esc(n.status)}</span><small>${n.attempts} attempt(s)</small></td><td style="white-space:normal">${esc(n.detail||'Waiting for the main PC and internet')}</td></tr>`))}</div>`}
function internalContact(id){const r=S.internal_contacts.find(r=>r.id===id)||{};formModal('Internal WhatsApp recipient',`${field('Staff / owner name','name',r.name,'text','required')}${field('Mobile number','phone',r.phone,'tel','required')}<label class="check"><input type="checkbox" name="opt_in" ${r.opt_in?'checked':''}> This recipient agreed to internal WhatsApp updates</label>`,data=>mutate('internal_contact',{...data,id},'Recipient saved.'))}
function whatsappSettings(){const s=S.settings;formModal('WhatsApp Business automation',`<label class="check"><input type="checkbox" name="whatsapp_enabled" ${s.whatsapp_enabled?'checked':''}> Enable notifications on the main PC</label><div class="form-grid">${field('Meta sender phone-number ID','whatsapp_phone_id',s.whatsapp_phone_id)}${field('Supported Graph API version','whatsapp_api_version',s.whatsapp_api_version,'text','placeholder="Use version from your Meta console"')}${field('Template language code','whatsapp_language',s.whatsapp_language)}${field('Access token (blank keeps existing)','token','','password','autocomplete="new-password"')}${field('Approved invoice template','whatsapp_invoice_template',s.whatsapp_invoice_template)}${field('Approved payment template','whatsapp_payment_template',s.whatsapp_payment_template)}${field('Approved internal update template','whatsapp_internal_template',s.whatsapp_internal_template)}${field('Daily summary time (optional, PC local time)','whatsapp_daily_time',s.whatsapp_daily_time,'time')}</div>${['low_stock','transfers','purchases'].map(k=>`<label class="check"><input type="checkbox" name="whatsapp_${k}" ${s['whatsapp_'+k]?'checked':''}> ${k.replaceAll('_',' ')}</label>`).join('')}<div class="help">Use approved body-only templates with exactly three text parameters: invoice = customer, invoice number, amount; payment = customer, amount, note; internal = business, update type, summary. Configure matching language codes in Meta. Recipients must opt in. Meta account setup and messaging charges apply. The token stays on this PC; Windows protects it for your Windows account.</div>`,data=>{for(const key of ['whatsapp_enabled','whatsapp_low_stock','whatsapp_transfers','whatsapp_purchases'])data[key]=data[key]==='on';return mutate('whatsapp_settings',data,'WhatsApp configuration saved.')})}
async function sendNotifications(){try{const r=await api('whatsapp_send');await load();toast(r.message||'Processed '+r.processed+' queued notification(s).')}catch(e){toast(e.message,true)}}

function cloudPairForm(){formModal('Connect this PC to your online business',`${field('Server HTTPS address','url','https://alhidaya.15.206.100.58.sslip.io','url','required')}${field('One-time pairing code','code','','password','required autocomplete="off"')}${field('Name for this PC','name',S.settings.device_name||'Warehouse Till','text','required')}<label class="check"><input type="checkbox" name="replace_sample" required> This PC contains only sample/test records. Replace them with the server records after a backup.</label><div class="help">Existing local records are backed up first. This flow does not merge real trading records. Pairing codes expire after 10 minutes. The owner chooses the location and stock allowance. This temporary server is scheduled for deletion; use a permanent server for live business.</div>`,async data=>{data.replace_sample=data.replace_sample==='on';const r=await api('cloud_pair',data);cart=[];window.saleParty='';await load();toast(r.message)},'Back up & connect')}
